const COLORS = ['#ff2d55', '#ff7a00', '#ffd60a', '#32d74b', '#00c7be', '#0a84ff', '#5e5ce6', '#bf5af2'];

function fixed(n: number): number {
  return Math.round(n * 10) / 10;
}

export function get(app: any, context: any) {
  const W = Math.max(1, Math.round(context.targetWidth || context.imageWidth || app.frame.width || 1200));
  const H = Math.max(1, Math.round(context.targetHeight || context.imageHeight || app.frame.height || 1600));
  const cx = W / 2;
  const cy = H / 2;
  const S = Math.min(W, H);
  const full = app.state.clockFit === 'full';
  const style = app.state.rainbowStyle || 'prism';
  const showDigital = app.state.showDigitalClock !== false;
  const showWhiteOutline = app.state.showWhiteOutline !== false;
  const r = S * (full ? (showWhiteOutline ? 0.455 : 0.49) : (showWhiteOutline ? 0.34 : 0.36));
  const outer = Math.sqrt(W * W + H * H);
  const d = new Date();
  const hr = d.getHours() % 12;
  const mn = d.getMinutes();
  const sc = d.getSeconds();
  const timeText = `${String(d.getHours()).padStart(2, '0')}:${String(mn).padStart(2, '0')}`;

  const hand = (angle: number, length: number, width: number, color: string) => {
    const a = angle - Math.PI / 2;
    return <line x1={cx} y1={cy} x2={fixed(cx + Math.cos(a) * length)} y2={fixed(cy + Math.sin(a) * length)} stroke={color} strokeWidth={fixed(width)} strokeLinecap="round" />;
  };

  const background = style === 'aurora' ? '#071a2a' : style === 'confetti' ? '#180d28' : style === 'ribbons' ? '#10142d' : style === 'spectrum' ? '#171126' : '#07111f';

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H}>
      <defs>
        {COLORS.map((color, i) => {
          const a = (i / COLORS.length) * Math.PI * 2;
          return <linearGradient id={`g${i}`} gradientUnits="userSpaceOnUse" x1={cx} y1={cy} x2={fixed(cx + Math.cos(a) * W)} y2={fixed(cy + Math.sin(a) * H)}><stop offset="0" stopColor={color} stopOpacity="0.94" /><stop offset="1" stopColor={COLORS[(i + 1) % COLORS.length]} stopOpacity="0.5" /></linearGradient>;
        })}
        <radialGradient id="soft" gradientUnits="userSpaceOnUse" cx={cx} cy={cy} r={fixed(S * 0.72)}><stop offset="0" stopColor="#fff7d6" stopOpacity="0.62" /><stop offset="0.42" stopColor="#ffffff" stopOpacity="0.08" /><stop offset="1" stopColor={background} stopOpacity="0.26" /></radialGradient>
      </defs>
      <rect width={W} height={H} fill={background} />
      {style === 'prism' && Array.from({ length: 48 }, (_, i) => {
        const a1 = (i / 48) * Math.PI * 2;
        const a2 = ((i + 1.05) / 48) * Math.PI * 2;
        return <path d={`M ${fixed(cx)} ${fixed(cy)} L ${fixed(cx + Math.cos(a1) * outer)} ${fixed(cy + Math.sin(a1) * outer)} L ${fixed(cx + Math.cos(a2) * outer)} ${fixed(cy + Math.sin(a2) * outer)} Z`} fill={`url(#g${i % COLORS.length})`} opacity={i % 2 ? 0.46 : 0.68} />;
      })}
      {style === 'aurora' && Array.from({ length: 12 }, (_, k) => <circle cx={cx} cy={cy} r={fixed(r * (1.18 + k * 0.16))} fill="none" stroke={COLORS[k % COLORS.length]} strokeWidth={fixed(S * 0.048)} opacity={0.32} />)}
      {style === 'ribbons' && Array.from({ length: 10 }, (_, i) => {
        const y = fixed(H * (0.08 + i * 0.095));
        const bend = fixed(S * (0.12 + (i % 3) * 0.04));
        return <path d={`M ${fixed(-S * 0.15)} ${y} C ${fixed(W * 0.26)} ${fixed(y - bend)}, ${fixed(W * 0.68)} ${fixed(y + bend)}, ${fixed(W + S * 0.15)} ${y}`} fill="none" stroke={COLORS[i % COLORS.length]} strokeWidth={fixed(S * 0.075)} strokeLinecap="round" opacity="0.48" />;
      })}
      {style === 'spectrum' && Array.from({ length: COLORS.length }, (_, i) => {
        const top = fixed((H / COLORS.length) * i);
        return <path d={`M 0 ${top} L ${W} ${fixed(top - H * 0.12)} L ${W} ${fixed(top + H / COLORS.length + H * 0.12)} L 0 ${fixed(top + H / COLORS.length)} Z`} fill={COLORS[i]} opacity="0.48" />;
      })}
      {style === 'confetti' && Array.from({ length: 90 }, (_, i) => {
        const a = i * 2.39996;
        const distance = S * (0.12 + ((i * 37) % 100) / 100 * 0.7);
        const size = S * (0.012 + (i % 4) * 0.004);
        return <circle cx={fixed(cx + Math.cos(a) * distance)} cy={fixed(cy + Math.sin(a) * distance)} r={fixed(size)} fill={COLORS[i % COLORS.length]} opacity="0.75" />;
      })}
      {style !== 'none' && <rect width={W} height={H} fill="url(#soft)" />}
      {showWhiteOutline && <circle cx={cx} cy={cy} r={fixed(r * 1.09)} fill="#fffaf0" opacity="0.88" />}
      <circle cx={cx} cy={cy} r={fixed(r)} fill="#101827" opacity="0.93" />
      <circle cx={cx} cy={cy} r={fixed(r * 0.89)} fill="none" stroke="#ffffff" strokeWidth={fixed(S * 0.012)} opacity="0.18" />
      {Array.from({ length: 60 }, (_, i) => {
        const a = (i / 60) * Math.PI * 2 - Math.PI / 2;
        const major = i % 5 === 0;
        const ro = r * 0.93;
        const ri = r * (major ? 0.78 : 0.84);
        return <line x1={fixed(cx + Math.cos(a) * ri)} y1={fixed(cy + Math.sin(a) * ri)} x2={fixed(cx + Math.cos(a) * ro)} y2={fixed(cy + Math.sin(a) * ro)} stroke={COLORS[Math.floor((i / 60) * COLORS.length) % COLORS.length]} strokeWidth={fixed(S * (major ? 0.01 : 0.005))} strokeLinecap="round" opacity="0.98" />;
      })}
      {Array.from({ length: 12 }, (_, i) => {
        const n = i + 1;
        const a = (n / 12) * Math.PI * 2 - Math.PI / 2;
        return <text x={fixed(cx + Math.cos(a) * r * 0.64)} y={fixed(cy + Math.sin(a) * r * 0.64)} textAnchor="middle" dominantBaseline="middle" fontFamily="Ubuntu" fontSize={fixed(S * 0.052)} fontWeight="700" fill={COLORS[i % COLORS.length]}>{n}</text>;
      })}
      {hand(((hr + mn / 60) / 12) * Math.PI * 2, r * 0.42, S * 0.025, '#ffd60a')}
      {hand(((mn + sc / 60) / 60) * Math.PI * 2, r * 0.62, S * 0.017, '#64d2ff')}
      {hand((sc / 60) * Math.PI * 2, r * 0.72, S * 0.007, '#ff375f')}
      <circle cx={cx} cy={cy} r={fixed(S * 0.034)} fill="#ffffff" />
      <circle cx={cx} cy={cy} r={fixed(S * 0.02)} fill="#ff2d55" />
      {showDigital && <text x={cx} y={fixed(cy + r * (full ? 0.73 : 1.33))} textAnchor="middle" fontFamily="Ubuntu" fontSize={fixed(S * (full ? 0.042 : 0.055))} fontWeight="700" fill="#fffaf0">{timeText}</text>}
    </svg>
  );
}
